@rendermode InteractiveServer
@inject Services.WarehouseStateService WarehouseState
@implements IDisposable

<div class="warehouse-selector">
    <label class="form-label mb-0 me-2 text-white" for="warehouseDropdown">Warehouse:</label>
    <select id="warehouseDropdown"
            class="form-select form-select-sm d-inline-block w-auto"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in Services.WarehouseStateService.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleStateChanged;
    }

    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            await WarehouseState.SetWarehouseAsync(newId);
        }
    }

    private Task HandleStateChanged()
    {
        InvokeAsync(StateHasChanged);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleStateChanged;
    }
}

