@page "/dashboard"
@rendermode InteractiveServer
@inject Services.WarehouseStateService WarehouseState
@inject Services.InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard – @WarehouseState.CurrentWarehouse.Name</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-header">
        <strong>@WarehouseState.CurrentWarehouse.Name</strong>
    </div>
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="display-4">
            <span class="badge @(AlertService.CurrentLowStockCount > 0 ? "bg-danger" : "bg-success")">
                @AlertService.CurrentLowStockCount
            </span>
        </p>
        <p class="text-muted">
            Items below minimum stock level. Refreshes every 10 seconds.
        </p>
    </div>
</div>

<div class="alert alert-info">
    <strong>How it works:</strong> This page subscribes to the polling service on load
    and unsubscribes when you navigate away. The sidebar badge and this card both
    receive updates from the same shared <code>InventoryAlertService</code>.
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleStateChanged;
        AlertService.OnAlertDataChanged += HandleAlertDataChanged;
        AlertService.Subscribe();
    }

    private Task HandleStateChanged()
    {
        InvokeAsync(StateHasChanged);
        return Task.CompletedTask;
    }

    private Task HandleAlertDataChanged()
    {
        InvokeAsync(StateHasChanged);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleStateChanged;
        AlertService.OnAlertDataChanged -= HandleAlertDataChanged;
        AlertService.Unsubscribe();
    }
}

